def compute(vars):
    base_value = vars["v1"]
    current_value = vars["v2"]

    if base_value == 0:
        return None

    change = current_value - base_value
    change_ratio = change / base_value
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "base_value": base_value,
            "current_value": current_value,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
